{!REQUIRESCRIPT("/apex/dsfs__DocuSign_JavaScript")} 
{!REQUIRESCRIPT("/soap/ajax/25.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/30.0/apex.js")} 

//**Note change made by Mark Jennison 16/10 to line 'if(prod==true)' **/ 
//**Note change made by Vinutha Iyengar Nov/17, case#06462026 to check for attachment count if standard contract **/ 
//**Note change made by Amarendra Nallamalli Jul/18, case#07945998 UK Non-Standard Contracting Process with DocuSign **/ 
//** Note change made by Vinutha Iyengar Aug/19, case# 08448469 Updates made for DocuSign version 7 and above 

//********* Option Declarations (Do not modify )*********// 
var RC = '';var RSL='';var RSRO='';var RROS='';var CCRM='';var CCTM='';var CCNM='';var CRCL=''; var CRL='';var OCO='';var DST='';var LA='';var LF='';var CEM='';var CES='';var STB='';var SSB='';var SES='';var SEM='';var SRS='';var SCS ='';var RES=''; 

//*************************************************// 

//************** Signer Logic ***************// 
var financialController = ''; 
var internalSigner = ''; 
var customerSigners = ''; 
var internalOrder = 0; 
var ccSigners = ''; 
var totalAttachments = 0; 
var intSigningOrder = 0; 
var custSigningOrder =0; 
var CustomerSignFirst; 

/*case#07945998 - Based on IME_Signing_Order__c value, the order of signing will change on the contract. 
If IM signs first - Order of signing - internalSigner,customerSigners,ccSigner 
Client signs first - Order of signing - customerSigners,internalSigner,ccSigner 
*/ 
if('{!IME_Signature_Information__c.IME_Signing_Order__c}' == 'IM signs first'){ 
CustomerSignFirst = false; 
intSigningOrder++; 
custSigningOrder++; 
}else if('{!IME_Signature_Information__c.IME_Signing_Order__c}' == 'Client signs first'){ 
CustomerSignFirst = true; 
} 



var debug = false;//** changed by M Jennison 10/10 **// 
var prod = true; 


// Query for customer signers 
var contactResult = sforce.connection.query("SELECT IME_Contact__r.Name, IME_Contact__r.Email, IME_Routing_Order__c FROM IME_Signatory_Contact__c WHERE IME_DocuSign_Contract_Envelope__c = '{!IME_Signature_Information__c.Id}' ORDER BY IME_Routing_Order__c ASC"); 
var contactRecords = contactResult.getArray("records"); 

// Construct Customer Signer CRL 
for(var i=0;i<contactRecords.length;i++){ 
custSigningOrder++; 
customerSigners = customerSigners+'Email~'+contactRecords[i].IME_Contact__r.Email+';LastName~'+contactRecords[i].IME_Contact__r.Name+';Role~Signer '+(i+1)+';RoutingOrder~'+custSigningOrder+','; 
} 


/*Case # 06462026 - Below code is used to change the Order of attachments and 
for Case # 07945998 - Added condition like below oder of attachment code will only be applicable for standard contract */ 
var standardContractResult = sforce.connection.query("select IME_Contract__r.Standard_Contract__c from IME_Signature_Information__c where IME_Contract__c = '{!Contract.Id}'"); 

var standardcontractrecords = standardContractResult.getArray("records"); 
if(standardcontractrecords[0].IME_Contract__r.Standard_Contract__c == 'true'){ 

var contractAttachment = sforce.apex.execute("updateContractOrder","updateContractFileOrder",{signatureId:"{!IME_Signature_Information__c.Id}"}); 
} 

// Below code changed by M Jennison 6/3/2017 Case 06380979 

// Construct Internal Signer CRL 
if(CustomerSignFirst)intSigningOrder=custSigningOrder+1; 
if(CustomerSignFirst) 
{ 
var ccSigingOrder=intSigningOrder+1; 
} 
else 
{ 
var ccSigingOrder=custSigningOrder+1; 
} 

if(prod==false) 
{ 
if( '{!IME_Signature_Information__c.IME_Internal_Signatories__c}' == 'Default Signatory' ) { 
internalSigner = 'SigningGroup~UKIDefault_Test;Role~Internal Signer;RoutingOrder~'+intSigningOrder; 
} else if ( '{!IME_Signature_Information__c.IME_Internal_Signatories__c}' == 'High Level Signatory' ) { 
internalSigner = 'SigningGroup~UKIHighLevel_Test;Role~Internal Signer;RoutingOrder~'+intSigningOrder; 
} else if ( '{!IME_Signature_Information__c.IME_Internal_Signatories__c}' == 'Novation or NDA' ) { 
internalSigner = 'SigningGroup~UKINovNDA_Test;Role~Internal Signer;RoutingOrder~'+intSigningOrder; 
} 
// Construct Carbon Copy Signer 
ccSigner= ',SigningGroup~UKICCRecipients_Test;Role~CC Signer;RoutingOrder~'+ccSigingOrder; 
} 
else 
{ 
if( '{!IME_Signature_Information__c.IME_Internal_Signatories__c}' == 'Default Signatory' ) { 
internalSigner = 'SigningGroup~UKIDefault;Role~Internal Signer;RoutingOrder~'+intSigningOrder; 
} else if ( '{!IME_Signature_Information__c.IME_Internal_Signatories__c}' == 'High Level Signatory' ) { 
internalSigner = 'SigningGroup~UKIHighLevel;Role~Internal Signer;RoutingOrder~'+intSigningOrder; 
} else if ( '{!IME_Signature_Information__c.IME_Internal_Signatories__c}' == 'Novation or NDA' ) { 
internalSigner = 'SigningGroup~UKINovNDA;Role~Internal Signer;RoutingOrder~'+intSigningOrder; 
} 
// Construct Carbon Copy Signer 
ccSigner= ',SigningGroup~UKICCRecipients;Role~CC Signer;RoutingOrder~'+ccSigingOrder; 
} 


// Above code changed by M Jennison 6/3/2017 Case 06380979 

//*************************************************// 

// Custom Contact Role Map (default config role) 
CCRM = 'Signer 1~Signer 5;Signer 2~Signer 6;Signer 3~Signer 7;Signer 4~Signer 8;Financial Controller~Financial Controller;Internal Signer~Internal Signer;CC Signer~CC Signer'; 

// Custom Contact Type Map (default Signer) 
CCTM = 'CC Signer~Carbon Copy'; 

// Custom Recipient List 
//CRL = financialController + customerSigners + internalSigner + ccSigner; 

if('{!IME_Signature_Information__c.IME_Signing_Order__c}' == 'IM signs first'){ 
CRL = internalSigner +','+ customerSigners +','+ ccSigner; 
}else if('{!IME_Signature_Information__c.IME_Signing_Order__c}' == 'Client signs first'){ 
CRL = customerSigners + internalSigner +','+ ccSigner; 
} 

/*case#07945998 UK Non-Standard Contracting Process with DocuSign. 
OCO tag is setting based on value Contract_Type__c field 
If Contract_Type__c field is IM Non Standard or Customer setting OCO tag to 'tag',If IM Standard OCO tag setting to 'Send'*/ 
var ContractResult = sforce.connection.query("select IME_Contract__r.Contract_Type__c from IME_Signature_Information__c where IME_Contract__c = '{!Contract.Id}'"); 

var contractrecords = ContractResult.getArray("records"); 
// One Click Option (default edit envelope screen) 
if(prod==false) //** Changed by Mark Jennison 15/10 from 'false' to 'true' to avoid DS screen in testing. This value should be 'false' in Production **/ 
{ 
if(contractrecords[0].IME_Contract__r.Contract_Type__c == 'IM Non Standard' || contractrecords[0].IME_Contract__r.Contract_Type__c == 'Customer') 
{ 
OCO = 'Tag'; //'Tag' to be used for non-Production and True for Non-standard contract 
} 
else 
{ 
OCO = 'Tag'; //'Tag' to be used for non-Production 
} 
} 
else 
{ 
if(contractrecords[0].IME_Contract__r.Contract_Type__c == 'IM Non Standard' || contractrecords[0].IME_Contract__r.Contract_Type__c == 'Customer') 
{ 
OCO = 'Tag'; //'Tag' used for Non-standard contract 
} 
else 
{ 
OCO = 'Send'; 
} 
} 

// Load Attachments (default on) 
LA = ''; 

// Custom Email Message (default in config) 
CEM = '{!URLENCODE(JSENCODE(IME_Signature_Information__c.IME_Email_Message__c))}'.replace(/%0D%0A/g, '\\n'); 

// Custom Email Subject (default in config) 
CES = '{!JSENCODE( IME_Signature_Information__c.IME_Email_Subject__c )}'; 

// Reminder and Expiration Settings 
RES = '{!IME_Signature_Information__c.IME_EnableReminders__c},{!IME_Signature_Information__c.IME_ReminderDays__c},{!IME_Signature_Information__c.IME_ReminderRepeatDays__c},{!IME_Signature_Information__c.IME_ExpireVoid__c},{!IME_Signature_Information__c.IME_ExpireNDays__c},{!IME_Signature_Information__c.IME_ExpireWarnNDays__c}'; 

// perform validation checks on envelope before sending 
function validateCriteria( ) 
{ 
var isValid = false; 
var errorList = ""; 

// validate attachments and recipients 
if ( !isValidAttachment() ) { errorList += " - The envelope is missing attachments.\n"; } 
if ( !isValidRecipient() ) { errorList += " - No recipients have been specified for the envelope.\n"; } 
//if ( !isValidReminder() ) { errorList += " - Invalid values were placed in the //Reminder fields.\n"; } 

if ( errorList.length == 0 ) 
{ 
isValid = true; 
} 

if ( !isValid ) 
{ 
var errorMessage = "Before sending, please correct the following errors:\n" + errorList; 
alert( errorMessage ); 
} 

return isValid; 
} 

function isValidReminder() 
{ 
var isValid = false; 

isValid = {!IME_Signature_Information__c.IME_EnableReminders__c}; 

return isValid; 
} 

function isValidAttachment( ) 
{ 

var isValid = false; 
var anyAttachment = 'Not Found'; 

try 
{ 
var result = sforce.connection.query("Select Id From Attachment where ParentId = '{!IME_Signature_Information__c.Id}' LIMIT 5"); 

var records = result.getArray("records"); 

totalAttachments = records.length; 
if (records.length != 0) 
{ 
anyAttachment = 'Records Found'; 
isValid = true; 
} 
} 
catch(error) 
{ 
if (debug) 
{ 
alert('Exception Name: '+error.name+ 'Exception Message:' + error.message); 
} 
} 
finally 
{ 
if (debug) 
{ 
alert('Finally - isValidAttachment: anyAttachment = ' + anyAttachment); 
} 
} 
return isValid; 
} 

function isValidRecipient( ) 
{ 
var isValid = false; 
var anyRecipients = 'Not Found'; 

try 
{ 
var result = sforce.connection.query("Select Id From IME_Signatory_Contact__c where IME_DocuSign_Contract_Envelope__c = '{!IME_Signature_Information__c.Id}' LIMIT 1"); 

var records = result.getArray("records"); 

if (records.length != 0) 
{ 
anyRecipients = 'Records Found'; 
isValid = true; 
} 
} 
catch(error) 
{ 
if (debug) 
{ 
alert('Exception Name: '+error.name+ 'Exception Message:' + error.message); 
} 
} 
finally 
{ 
if (debug) 
{ 
alert('Finally - isValidRecipient: anyRecipients = ' + anyRecipients); 
} 
} 
return isValid; 
} 


function confirmSending() 
{ 
var oppUp ="{!IME_Signature_Information__c.sent_for_signature__c}"; 
if(oppUp == 1){ 
alert('The contract has already been fully executed, this cannot be sent again for signature.'); 
} 
else 
{ 
return confirm( "Clicking on \"OK\" will send the Contract for Signatory to all Recipients. Are you sure?" ); 
} 
} 

var newLocation = "/apex/dsfs__DocuSign_CreateEnvelope?DSEID=0&SourceID={!IME_Signature_Information__c.Id}&CCRM="+CCRM+"&CCTM="+CCTM+"&CRL="+CRL+"&OCO="+OCO+"&LA="+LA+"&CEM="+CEM+"&CES="+CES+"&RES="+RES; 

// validate the form contents 
if ( validateCriteria() ) 
{ 
// confirm the user is ready to send the form 
if ( confirmSending() ) 
{ 
// if debug then show destination else go 
//********* Page Callout (Do not modify) *********// 
if ( debug ) 
{ 
alert( newLocation ); 
} 
else 
{ 
//**Note change made by Vinutha Iyengar Nov/17, case#06462026 to check for attachment count if standard contract **/ 
if(totalAttachments!=2 && {!IME_Signature_Information__c.Standard_Contract__c}) 
{ 
alert("Schedule A is not attached. Contract could not be sent."); 
} 
else 
{ 
//window.location.href = newLocation; 
console.log(newLocation); 
CRL=CRL.replace(',,', ',');
window.location.href = "{!URLFOR('/apex/dsfs__DocuSign_CreateEnvelope',null,[SourceID=IME_Signature_Information__c.Id])}&CCRM="+CCRM+"&CCTM="+CCTM+"&CRL="+CRL+"&OCO="+OCO+"&LA="+LA+"&CEM="+CEM+"&CES="+CES+"&RES="+RES; 

} 
} 
//*******************************************// 
} 
}
